import sys
B='/home/claude/wpi/run/out/dashboard/'
def run(fn,pairs):
    s=open(B+fn).read()
    for p in pairs:
        old,new=p[0],p[1]; allr=len(p)>2
        c=s.count(old)
        assert (c>=1 if allr else c==1),(fn,c,old[:70])
        s=s.replace(old,new)
    open(B+fn,'w').write(s)
